function OverseaClubBossRecordDialog:InitLeftTab()
    local TabDataConfig = {
        {  name = localize("社团记录"),
                 recordType    = ClubUtils.RecordType.Club,
                 func        = Bind(self, self.OnClickTabHandler_),
        },
        {  name = localize("我的记录"),
                 recordType    = ClubUtils.RecordType.MySelf,
                 func        = Bind(self, self.OnClickTabHandler_),
        }
    }

    local bossDojo = ClubUtils.GetClubComp():GetBossDojo()
    local bossInfo = bossDojo:GetBossInfo()
    for i, v in pairs(bossInfo) do
        local vo = ClubUtils.GetBossPassVo(v.questId)
        if next(vo) then
            v.vo = vo
        end
    end

    table.sort(bossInfo,function(a,b)
        if a.vo.bossTypes == b.vo.bossTypes then
            return a.vo.id < b.vo.id
        else
            return a.vo.bossTypes < b.vo.bossTypes
        end
    end)

    local tabData = {}
    for i, v in pairs(bossInfo) do
        local name = ChallengeTypeName.Normal
        local bossData = v
        if v.vo.bossTypes == ClubUtils.BossType.BigBoss then
            name = ChallengeTypeName.Special
        end
        local IconType = self:GetIconTypeByBossData(v)
        table.insert(tabData,{name = name,questId = bossData.questId,IconType = IconType,func = Bind(self,self.OnClickChildTabHandler_)})
    end

    local TabChildConfig = {
        [1] = tabData,

        [2] = tabData,
    }
    self.taskTypeTabEnv_:Refresh(TabDataConfig, TabChildConfig, 1, 1)
end

function OverseaClubBossRecordDialog:GetIconTypeByBossData(v)
    local type = 1
    local bossData = QuestConfMgr:GetInstance():GetAllQuestLineupVo(v.questId)
    for i, v in pairs(bossData) do
        for k, j in pairs(v.wave1NpcType) do
            if tonumber(j) == Constants.RoleClass.Boss then
                return v.attribute[k]
            end
        end
    end
    return type
end

function OverseaClubBossRecordDialog:OnClickTabHandler_(tabData)
    self.recordType = tabData.recordType
end

function OverseaClubBossRecordDialog:OnClickChildTabHandler_(data)
    self.questId = data.questId
    self.showData = self:GetRecordData(self.recordData)
    --- 清空通用筛选里的选项
    self:ClearFilterNodeGroup()
    self:SetRecordStatus()
    self:RefreshGridView()
end

function OverseaClubBossRecordDialog:GetRecordData()
    local isMe = self.recordType == ClubUtils.RecordType.MySelf
    local recordData = self:GetRecordDataByQuestId(self.questId,isMe)
    return recordData
end

function OverseaClubBossRecordDialog:SetRecordStatus()
    local status = table.count(self.showData) > 0
    KTool.SetActive(self.ScrollView.gameObject,status)
    KTool.SetActive(self.EmptyNode.gameObject,not status)
end

function OverseaClubBossRecordDialog:GetRecordDataByQuestId(questId,isMe)
    local data = {}
    for i, v in pairs(self.recordData) do
        if v.questId == questId then
            if isMe then
                if v.playerId == checkNumber(playerComp.playerDojo:PlayerId()) then
                    table.insert(data,v)
                end
            else
                table.insert(data,v)
            end
        end
    end
    return data
end

function OverseaClubBossRecordDialog:ClearFilterNodeGroup()
    ---@type UICommonFilterMB
    local env = self:GetFilterNodeEnv()
    if isNull(env) then return end
    env:SetDefGroups({})
end

function OverseaClubBossRecordDialog:FreshFilterNode()
    ---@type UIAreaFilterMB
    local filterNodeEnv = self:GetFilterNodeEnv()
    if isNull(filterNodeEnv) then return end
    ---@type UICommonFilterMB
    local sortType = Constants.UISortType.ClubRecord
    local showData = self:GetAllRecordData()
    filterNodeEnv:SetFilterClass(Constants.UIFilterType.ClubRecord)
    filterNodeEnv:SetCallback( showData,function(data)
        self.recordData = showData
        self.showData = self:GetRecordData()
        self:SetRecordStatus()
        self:RefreshGridView()
    end, sortType)
    filterNodeEnv:RestoreState("OverseaClubBossRecordDialog", function(data)
        self.recordData = data
        --self:RefreshGridView(self.showData)
    end)
end

function OverseaClubBossRecordDialog:GetAllRecordData()
    local bossDojo = ClubUtils.GetClubComp():GetBossDojo()
    local recordData = bossDojo:GetRecord()
    return recordData
end

function OverseaClubBossRecordDialog:RefreshGridView()
    if self.ScrollView then
        if not self.ScrollView.IsListViewInit then
            self.ScrollView:InitListView(#self.showData, Bind(self, self.OnRefreshCellIndex))
            self.ScrollView:UpdateDisplayItemCount("Cell")
        else
            GameUtils.ReloadData(self.ScrollView, #self.showData)
        end
        self.ScrollView:MovePanelToItemIndex(0,0)
    end
end

function OverseaClubBossRecordDialog:OnRefreshCellIndex(listView,index)
    if index < 0 or index >= #self.showData then
        return
    end
    local cell = listView:NewListViewItem("Cell")
    local data = self.showData[index + 1]
    ---@type OverseaClubBossRecordDialogCell
    local scr = CfUtils.GetLuaScr(cell, UIRecordCellPath)
    if scr then
        scr:RefreshShow(data)
        if listView.DisplayItemNumber < listView.DisplayItemCount then
            scr:PlayDelayAnimByShow(listView.DisplayItemNumber)
            listView.DisplayItemNumber = listView.DisplayItemNumber + 1
        else
            scr:PlayAnimByIdle()
        end
    end
    return cell
end

